export interface CoreConcept {
  /** Stable id, used in URLs and saved preferences. */
  id: string;
  name: string;
  /** How it's built — shown as a badge in the gallery. */
  kind: "3D" | "2.5D" | "2D";
  /** One line, shown under the name. */
  tagline: string;
  /** A short paragraph describing the look and how it reacts. */
  description: string;
  /** How it reacts to typing, in one short sentence — shown in the gallery. */
  typing: string;
  /** Canvas half-size relative to the core radius (room for glows/coronas outside the sphere). */
  extent: number;
  /** GLSL defining `vec4 core(vec2 uv)` — premultiplied rgba. Has access to everything in prelude.ts. */
  frag: string;
}
import type { CoreConcept } from "../types";

/** Placeholder — replaced by the real concept. */
export const membrane: CoreConcept = {
  id: "membrane",
  name: "Liquid Membrane",
  kind: "3D",
  tagline: "Iridescent soap-film sphere",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 1.6,
  frag: /* glsl */ `
vec4 core(vec2 uv) {
  vec2 P = uv / uRadius;
  float r = length(P);
  float pxW = uPx / uRadius;
  float a = 1.0 - smoothstep(1.0 - pxW, 1.0 + pxW, r);
  vec3 col = mix(vec3(0.05, 0.04, 0.12), vec3(0.01, 0.01, 0.03), r) + palette(r > 0.0 ? P.x / r : 0.0) * pow(r, 6.0) * 0.6;
  vec4 y = yFlat(P, 1.0, pxW);
  col = mix(col, y.rgb, y.a);
  return vec4(col * a, a);
}
`,
};
import type { CoreConcept } from "../types";

/** Placeholder — replaced by the real concept. */
