float mbR(vec3 n) {
  float t = uTime;
  float wob = 0.014 * sin(dot(n, vec3(2.1, 1.3, -0.8)) + t * 1.05)
            + 0.011 * sin(dot(n, vec3(-1.2, 2.6, 1.5)) - t * 1.31 + 1.7)
            + 0.008 * sin(dot(n, vec3(3.1, -1.4, 2.2)) + t * 1.73 + 4.1)
            + 0.004 * sin(dot(n, vec3(-5.7, -4.3, 3.1)) - t * 2.3 + 2.0);
  wob *= 1.0 + uEnergy * 0.9;
  vec3 ax = normalize(vec3(0.25, 1.0, 0.15));
  float c = dot(n, ax);
  float jig = uImpulse * (0.06 * (1.5 * c * c - 0.5) + 0.018 * c * (2.5 * c * c - 1.5));
  float breathe = 0.03 * uPulse;
  float rip = mbRipple(n, uWaveS.x, uWaveAge.x, uWaveSeed.x) + mbRipple(n, uWaveS.y, uWaveAge.y, uWaveSeed.y)
            + mbRipple(n, uWaveS.z, uWaveAge.z, uWaveSeed.z) + mbRipple(n, uWaveS.w, uWaveAge.w, uWaveSeed.w);
  return 0.955 + wob + jig + breathe + rip;
}

// Thin bright filaments of a gyroid-like web, warped so it flows like caustic light.
float mbCaustic(vec3 p, float t, float w) {
  vec3 q = p * 3.4;
  q += 0.55 * sin(q.yzx * 1.3 + vec3(t * 0.9, t * 1.1, t * 0.7));
  q += 0.3 * sin(q.zxy * 2.1 - vec3(t * 1.3, t * 0.8, t * 1.0));
  float v = sin(q.x) * cos(q.y) + sin(q.y) * cos(q.z) + sin(q.z) * cos(q.x);
  return exp(-v * v / (w * w));
}

// Studio environment for reflections.
vec3 mbEnv(vec3 r) {
  float key = smoothstep(0.45, 0.95, dot(r, normalize(vec3(-0.55, 0.72, 0.42))));
  float kick = smoothstep(0.7, 0.97, dot(r, normalize(vec3(0.95, -0.25, 0.2))));
  float floorB = smoothstep(0.2, -0.8, r.y);
  return vec3(0.78, 0.88, 1.0) * key * 0.85 + vec3(1.0, 0.32, 0.78) * kick * 0.55 + vec3(0.1, 0.16, 0.5) * floorB * 0.18;
}

vec4 core(vec2 uv) {
  vec2 P = uv / uRadius;
  float rP = length(P);
  float pxW = uPx / uRadius;
  bool light = uLight > 0.5;
  float e = uEnergy;
  float t = uTime;
  vec2 dirP = rP > 1e-5 ? P / rP : vec2(1.0, 0.0);
  float rs = mbR(vec3(dirP, 0.0));
  vec3 tint = palette(dirP.x * min(rP * 1.4, 1.0));
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  if (rP < rs + 2.0 * pxW) {
    // Front surface: solve |p| = R(p/|p|) along the view ray.
    float r2 = rP * rP;
    float z = sqrt(max(rs * rs - r2, 0.0));
    for (int i = 0; i < 3; i++) {
      vec3 nn = normalize(vec3(P, z + 1e-4));
      float Rn = mbR(nn);
      z = mix(z, sqrt(max(Rn * Rn - r2, 0.0)), 0.85);
    }
    vec3 S = vec3(P, z);
    vec3 n = normalize(S + vec3(0.0, 0.0, 1e-4));
    float r0 = mbR(n);
    vec3 up = abs(n.y) < 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
    vec3 t1 = normalize(cross(up, n));
    vec3 t2 = cross(n, t1);
    float fe = 0.012;
    float r1 = mbR(normalize(n + t1 * fe));
    float r2b = mbR(normalize(n + t2 * fe));
    vec3 N = normalize(n * r0 - (t1 * (r1 - r0) + t2 * (r2b - r0)) / fe);
    vec3 V = vec3(0.0, 0.0, 1.0);
    float ndv = clamp(N.z, 0.0, 1.0);
    float fres = pow(1.0 - ndv, 3.0);
    float fresThin = pow(1.0 - ndv, 6.0);

    // Refraction into the liquid.
    vec3 rd = refract(-V, N, 0.75);
    float b = dot(S, rd);
    float cc = dot(S, S) - 0.93 * 0.93;
    float disc = b * b - cc;
    float sExit = disc > 0.0 ? -b + sqrt(disc) : -b;
    sExit = max(sExit, 0.05);
    vec3 E = S + rd * sExit;

    // The Y, suspended inside.
    vec3 pB; float sB; float armB;
    float yS = 0.84;
    float minD = yTrace(S, rd, sExit, yS, pB, sB, armB);
    float cov = yCoverage(minD, pxW * 1.1);
    vec3 yCol = vec3(0.0);
    vec3 yBase = vec3(0.0);
    vec3 yHit = S + rd * sB;
    if (minD < 0.04) {
      yBase = yColor(pB.xy, armB);
      yCol = yShade(pB, armB, rd, 1.05 + uPulse * 0.4 + e * 0.25 + uKick * 0.35);
      float cY = mbCaustic(yHit * 1.2, t * 0.8, 0.35);
      yCol += mix(yBase, vec3(1.0), 0.6) * cY * 0.35;
    }
    float yHalo = minD < 0.04 ? exp(-max(minD, 0.0) * 55.0) * (1.0 - cov) : 0.0;

    // Interior: deep liquid with a caustic web on the far wall and a soft heart.
    float sMid = clamp(-dot(S, rd), 0.0, sExit);
    float cd = length(S + rd * sMid);
    vec3 deep = mix(vec3(0.02, 0.03, 0.13), vec3(0.05, 0.03, 0.18), smoothstep(-0.6, 0.6, E.x));
    float wallGraze = pow(1.0 - abs(dot(rd, normalize(E))), 2.0);
    vec3 body = deep + palette(E.x * 0.9) * wallGraze * 0.22;
    vec3 Ew = rotY(uSwirl * 0.35) * E;
    float cw = mbCaustic(Ew, t * 0.6, 0.18 + 0.1 * (1.0 - wallGraze));
    float cw2 = mbCaustic(Ew * 1.7 + 3.1, t * 0.75, 0.22);
    body += mix(vec3(0.2, 0.55, 1.0), vec3(0.75, 0.35, 1.0), smoothstep(-0.5, 0.6, E.x - E.y * 0.3)) * (cw * 0.5 + cw2 * 0.22) * (0.6 + uPulse * 0.6 + e * 0.4);
    float heart = exp(-cd * cd * 5.0);
    body += vec3(0.28, 0.24, 1.0) * heart * (0.22 + uPulse * 0.3 + e * 0.2);
    body += yBase * yHalo * (0.55 + uPulse * 0.3 + uKick * 0.4);
    body = mix(body, yCol, cov);
    // Absorption toward deep blue with depth through the liquid.
    float depthT = (cov > 0.5 ? sB : sExit);
    body *= mix(vec3(1.0), vec3(0.55, 0.7, 1.0), smoothstep(0.2, 1.8, depthT) * 0.6);

    // Membrane surface: flowing thin-film interference + creases.
    vec3 q = rotY(uSwirl * 0.25) * n;
    float th = fbm2(q * 1.7 + vec3(0.0, t * 0.06, t * 0.03));
    float rip = (r0 - 0.955) * 12.0;
    float phase = (th * 2.4 + rip * 0.35 + t * 0.05) * TAU / (0.55 + 0.45 * ndv);
    vec3 film = palette(cos(phase));
    float cr = 1.0 - abs(2.0 * fbm2(q * 2.3 + vec3(th * 1.6, t * 0.05, 0.0)) - 1.0);
    float crease = smoothstep(0.9, 0.985, cr);
    vec3 Rv = reflect(-V, N);
    vec3 env = mbEnv(Rv);
    vec3 Ld = normalize(vec3(-0.55, 0.72, 0.42));
    float sp = pow(max(dot(Rv, Ld), 0.0), 260.0);
    float spB = pow(max(dot(Rv, Ld), 0.0), 18.0);

    col = body * (1.0 - fres * 0.6);
    col += film * (0.07 + fres * 0.85 + fresThin * 0.6) * (1.0 + uPulse * 0.4);
    col += env * (0.08 + fres * 0.9);
    col += mix(film, vec3(0.85, 0.95, 1.0), 0.5) * crease * (0.12 + fres * 0.55);
    col += vec3(1.0) * sp * 1.6 + vec3(0.6, 0.75, 1.0) * spB * 0.05;
    // Inner reflection band just inside the outline.
    float inside = rs - rP;
    col += film * exp(-pow(inside / 0.035, 2.0)) * 0.35;
    col = tonemap(col);
    alpha = 1.0 - smoothstep(rs - pxW, rs + pxW, rP);
    col *= alpha;
  }

  if (rP > rs - 2.0 * pxW) {
    float d = max(rP - rs, 0.0);
    float bloom = exp(-d * 34.0) * 0.55 + exp(-d * 8.0) * (0.12 + e * 0.15 + uPulse * 0.12);
    vec3 c = tint * bloom;
    float a = bloom;
    a = clamp(a, 0.0, 1.0) * (light ? 0.45 : 1.0);
    c = min(c, vec3(a));
    col += c * (1.0 - alpha);
    alpha += a * (1.0 - alpha);
  }
  float dith = (hash2(gl_FragCoord.xy) - 0.5) / 255.0;
  col = clamp(col + dith * alpha, 0.0, 1.0);
  return vec4(min(col, vec3(alpha)), alpha);
}
