import type { CoreConcept } from "../types";

/**
 * Liquid Membrane — an iridescent liquid sphere. The surface is a radially displaced sphere
 * (organic wobble + capillary ripples + spring jiggle) solved per pixel by fixed-point iteration,
 * so the silhouette itself deforms. Thin-film colour, fresnel and a studio reflection sit on top
 * of a refracted, caustic-lit interior holding the 3D Y.
 */
export const membrane: CoreConcept = {
  id: "membrane",
  name: "Liquid Membrane",
  kind: "3D",
  tagline: "Iridescent soap-film sphere",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 1.6,
  frag: /* glsl */ `
// Impact point of a keystroke droplet, on the visible hemisphere (view space).
vec3 mbImpact(float s) {
  float a = fract(s * 7.31 + 0.13) * TAU;
  float b = fract(s * 13.97 + 0.41);
  float rho = 0.25 + 0.68 * b;
  return vec3(cos(a) * rho, sin(a) * rho, sqrt(max(1.0 - rho * rho, 0.0)));
}
float mbFade(float age) { return 1.0 - smoothstep(0.72, 1.08, age); }
float mbFrontPos(float age) { return 0.05 + age * 2.2; }

// One capillary ripple: a decaying sinusoid trailing an expanding front (geodesic distance).
float mbRipple(vec3 n, float S, float age, float seed) {
  if (S <= 0.0) return 0.0;
  float g = acos(clamp(dot(n, mbImpact(seed)), -1.0, 1.0));
  float front = mbFrontPos(age);
  float x = front - g;
  float env = smoothstep(-0.12, 0.05, x) * exp(-max(x, 0.0) * 2.2);
  float wave = sin(x * 25.0 + 0.6) * env;
  float crater = -exp(-g * g * 40.0) * exp(-age * 6.0) * 1.5;
  return (wave / (0.6 + front * 0.55) + crater) * S * mbFade(age) * 0.1;
}
// Glowing crest riding on each ripple front (for shading, not geometry).
float mbCrest(vec3 n, float S, float age, float seed) {
  if (S <= 0.0) return 0.0;
  float g = acos(clamp(dot(n, mbImpact(seed)), -1.0, 1.0));
  float x = mbFrontPos(age) - g;
  return S * mbFade(age) * (exp(-x * x * 900.0) + 0.35 * exp(-x * x * 60.0)) + S * exp(-g * g * 30.0) * exp(-age * 10.0) * 2.0;
}

// Displaced radius of the membrane in direction n.
float mbR(vec3 n) {
  float t = uTime;
  float wob = 0.014 * sin(dot(n, vec3(2.1, 1.3, -0.8)) + t * 1.05)
            + 0.011 * sin(dot(n, vec3(-1.2, 2.6, 1.5)) - t * 1.31 + 1.7)
            + 0.008 * sin(dot(n, vec3(3.1, -1.4, 2.2)) + t * 1.73 + 4.1)
            + 0.004 * sin(dot(n, vec3(-5.7, -4.3, 3.1)) - t * 2.3 + 2.0);
  wob *= 1.0 + uEnergy * 0.9;
  vec3 ax = normalize(vec3(0.25, 1.0, 0.15));
  float c = dot(n, ax);
  float jig = uImpulse * (0.075 * (1.5 * c * c - 0.5) + 0.022 * c * (2.5 * c * c - 1.5));
  float breathe = 0.035 * uPulse;
  float rip = mbRipple(n, uWaveS.x, uWaveAge.x, uWaveSeed.x) + mbRipple(n, uWaveS.y, uWaveAge.y, uWaveSeed.y)
            + mbRipple(n, uWaveS.z, uWaveAge.z, uWaveSeed.z) + mbRipple(n, uWaveS.w, uWaveAge.w, uWaveSeed.w);
  return 0.955 + wob + jig + breathe + rip;
}

// Thin bright filaments of a gyroid-like web, warped so it flows like caustic light.
float mbCaustic(vec3 p, float t, float w) {
  vec3 q = p * 3.4;
  q += 0.55 * sin(q.yzx * 1.3 + vec3(t * 0.9, t * 1.1, t * 0.7));
  q += 0.3 * sin(q.zxy * 2.1 - vec3(t * 1.3, t * 0.8, t * 1.0));
  float v = sin(q.x) * cos(q.y) + sin(q.y) * cos(q.z) + sin(q.z) * cos(q.x);
  return exp(-v * v / (w * w));
}

// Studio environment for reflections: a rounded softbox top-left, a magenta kicker right.
vec3 mbEnv(vec3 r) {
  vec3 kd = normalize(vec3(-0.55, 0.72, 0.42));
  vec3 ku = normalize(cross(kd, vec3(0.0, 0.0, 1.0)));
  vec3 kv = cross(ku, kd);
  vec2 kq = vec2(dot(r, ku), dot(r, kv)) / max(dot(r, kd), 0.05);
  vec2 kb = abs(kq) - vec2(0.34, 0.2);
  float box = dot(r, kd) > 0.0 ? 1.0 - smoothstep(-0.02, 0.06, length(max(kb, 0.0)) + min(max(kb.x, kb.y), 0.0) - 0.08) : 0.0;
  float key = smoothstep(0.3, 0.95, dot(r, kd));
  float kick = smoothstep(0.72, 0.97, dot(r, normalize(vec3(0.95, -0.25, 0.2))));
  float floorB = smoothstep(0.2, -0.8, r.y);
  return vec3(0.85, 0.92, 1.0) * (box * 0.9 + key * 0.25) + vec3(1.0, 0.32, 0.78) * kick * 0.55 + vec3(0.1, 0.16, 0.5) * floorB * 0.2;
}

// A crown of droplets thrown up by each impact, arcing out and falling back. Premultiplied.
vec4 mbSplash(vec2 P, float pxW, bool light) {
  vec3 acc = vec3(0.0);
  float a = 0.0;
  for (int k = 0; k < 4; k++) {
    float S = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    if (S <= 0.0) continue;
    float age = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    float seed = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
    if (age > 0.95) continue;
    vec3 c = mbImpact(seed);
    vec3 t1 = normalize(vec3(-c.y, c.x, 0.0) + vec3(1e-4, 0.0, 0.0));
    vec3 t2 = cross(c, t1);
    for (int j = 0; j < 6; j++) {
      float fj = float(j);
      float hj = hash2(vec2(seed * 91.0, fj));
      float ang = fj / 6.0 * TAU + seed * 17.0 + hj * 0.6;
      float sp = 0.75 + 0.5 * hj;
      float tt = age * sp;
      float rise = (1.5 * tt - 1.7 * tt * tt);        // up and back down
      if (rise <= 0.0) continue;
      vec3 lat = t1 * cos(ang) + t2 * sin(ang);
      vec3 p = c * (0.97 + rise * 0.55) + lat * tt * 0.42;
      float rad = (0.016 + 0.012 * hj) * (1.0 - smoothstep(0.4, 0.95, age));
      float d = length(P - p.xy);
      float bead = 1.0 - smoothstep(rad - pxW, rad + pxW, d);
      float glow = exp(-d / (rad * 2.2 + 0.004)) * 0.35;
      float hl = 1.0 - smoothstep(0.0, rad * 0.75, length(P - p.xy - vec2(-0.3, 0.35) * rad));
      vec3 bc = palette(cos(fj * 1.9 + seed * 9.0));
      vec3 cc = light ? bc * 0.55 * bead + vec3(1.0) * hl * bead * 0.8 : bc * (bead * 0.9 + glow) + vec3(1.0) * hl * bead * 0.9;
      float ca = light ? bead * 0.95 + glow * 0.25 : bead + glow;
      acc += cc * S * 1.33;
      a += ca * S * 1.33;
    }
  }
  a = clamp(a, 0.0, 1.0);
  return vec4(min(acc, vec3(a)), a);
}

vec4 core(vec2 uv) {
  vec2 P = uv / uRadius;
  float rP = length(P);
  float pxW = uPx / uRadius;
  bool light = uLight > 0.5;
  float e = uEnergy;
  float t = uTime;
  vec2 dirP = rP > 1e-5 ? P / rP : vec2(1.0, 0.0);
  float rs = mbR(vec3(dirP, 0.0));
  vec3 tint = palette(dirP.x * min(rP * 1.4, 1.0));
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  if (rP < rs + 2.0 * pxW) {
    // Front surface: solve |p| = R(p/|p|) along the view ray.
    float r2 = rP * rP;
    float z = sqrt(max(rs * rs - r2, 0.0));
    for (int i = 0; i < 3; i++) {
      vec3 nn = normalize(vec3(P, z + 1e-4));
      float Rn = mbR(nn);
      z = mix(z, sqrt(max(Rn * Rn - r2, 0.0)), 0.85);
    }
    vec3 S = vec3(P, z);
    vec3 n = normalize(S + vec3(0.0, 0.0, 1e-4));
    float r0 = mbR(n);
    vec3 up = abs(n.y) < 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
    vec3 t1 = normalize(cross(up, n));
    vec3 t2 = cross(n, t1);
    float fe = 0.012;
    float r1 = mbR(normalize(n + t1 * fe));
    float r2b = mbR(normalize(n + t2 * fe));
    vec3 N = normalize(n * r0 - (t1 * (r1 - r0) + t2 * (r2b - r0)) / fe);
    vec3 V = vec3(0.0, 0.0, 1.0);
    float ndv = clamp(N.z, 0.0, 1.0);
    float fres = pow(1.0 - ndv, 3.0);
    float fresThin = pow(1.0 - ndv, 6.0);
    float crest = mbCrest(n, uWaveS.x, uWaveAge.x, uWaveSeed.x) + mbCrest(n, uWaveS.y, uWaveAge.y, uWaveSeed.y)
                + mbCrest(n, uWaveS.z, uWaveAge.z, uWaveSeed.z) + mbCrest(n, uWaveS.w, uWaveAge.w, uWaveSeed.w);

    // Refraction into the liquid (ripples bend it gently so the Y stays legible).
    vec3 Nr = normalize(n + (N - n) * 0.4);
