    // Membrane surface: flowing thin-film interference + creases + crest glow.
    vec3 q = rotY(uSwirl * 0.25) * n;
    float th = fbm2(q * 1.7 + vec3(0.0, t * 0.06, t * 0.03));
    float rip = (r0 - 0.955) * 10.0;
    float phase = (th * 2.4 + rip * 0.45 + t * 0.05) * TAU / (0.55 + 0.45 * ndv);
    vec3 film = palette(cos(phase));
    float cr = 1.0 - abs(2.0 * fbm2(q * 2.3 + vec3(th * 1.6, t * 0.05, 0.0)) - 1.0);
    float crease = smoothstep(0.9, 0.985, cr);
    vec3 Rv = reflect(-V, N);
    vec3 env = mbEnv(Rv);
    vec3 Ld = normalize(vec3(-0.55, 0.72, 0.42));
