    col += env * (0.1 + fres * 0.85);
    col += mix(film, vec3(0.85, 0.95, 1.0), 0.5) * crease * (0.1 + fres * 0.5);
    col += mix(vec3(0.55, 0.9, 1.0), film, 0.4) * crest * 0.9;
    col += vec3(1.0) * sp * 1.6;
