    alpha = 1.0 - smoothstep(rs - pxW, rs + pxW, rP);
    col *= alpha;
  }

  if (rP > rs - 2.0 * pxW) {
    float d = max(rP - rs, 0.0);
    float bloom = exp(-d * 34.0) * 0.55 + exp(-d * 8.0) * (0.12 + e * 0.15 + uPulse * 0.15);
    vec3 c = tint * bloom;
    float a = bloom;
    a = clamp(a, 0.0, 1.0) * (light ? 0.45 : 1.0);
    c = min(c, vec3(a));
    col += c * (1.0 - alpha);
    alpha += a * (1.0 - alpha);
  }

  vec4 sp = mbSplash(P, pxW, light);
  col = col * (1.0 - sp.a) + sp.rgb;
  alpha = alpha + sp.a * (1.0 - alpha);

  float dith = (hash2(gl_FragCoord.xy) - 0.5) / 255.0;
  col = clamp(col + dith * alpha, 0.0, 1.0);
  return vec4(min(col, vec3(alpha)), alpha);
