import type { CoreConcept } from "../types";

/**
 * Particle Nebula — three nested shells of glowing dots on spherical Fibonacci lattices (looked up
 * per pixel, front and back hemispheres), wrapped by flowing dotted ribbons, around a crisp Y.
 * Keystrokes push a radial wave front through the dot field: dots are thrown outward past the
 * sphere's edge and spring back into formation.
 */
export const particles: CoreConcept = {
  id: "particles",
  name: "Particle Nebula",
  kind: "2.5D",
  tagline: "Ribbons of tiny points",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 1.75,
  frag: /* glsl */ `
const float PN_PHI = 1.61803398875;

float pnMadfrac(float a, float b) { float x = a * b; return x - floor(x); }

// Nearest point of an n-point spherical Fibonacci lattice (Keinert et al. 2015) to unit vector p.
// Returns the point's index; its centre goes to qBest.
float pnNearest(vec3 p, float n, out vec3 qBest) {
  float m = 1.0 - 1.0 / n;
  float phi = min(atan(p.y, p.x), PI);
  float cosT = p.z;
  float k = max(2.0, floor(log(n * PI * 2.2360679 * max(1.0 - cosT * cosT, 1e-6)) / log(PN_PHI * PN_PHI)));
  float Fk = pow(PN_PHI, k) / 2.2360679;
  float F0 = floor(Fk + 0.5);
  float F1 = floor(Fk * PN_PHI + 0.5);
  float b00 = TAU * pnMadfrac(F0 + 1.0, PN_PHI - 1.0) - TAU * (PN_PHI - 1.0);
  float b01 = TAU * pnMadfrac(F1 + 1.0, PN_PHI - 1.0) - TAU * (PN_PHI - 1.0);
  float b10 = -2.0 * F0 / n;
  float b11 = -2.0 * F1 / n;
  float det = b00 * b11 - b10 * b01;
  float X = phi;
  float Y = cosT - m;
  vec2 c = floor(vec2(b11 * X - b10 * Y, -b01 * X + b00 * Y) / (abs(det) < 1e-9 ? 1e-9 : det));
  float dBest = 8.0;
  float jBest = 0.0;
  qBest = vec3(0.0, 0.0, 1.0);
  for (int s = 0; s < 4; s++) {
    vec2 o = vec2(s == 1 || s == 3 ? 1.0 : 0.0, s >= 2 ? 1.0 : 0.0);
    float i = floor(dot(vec2(F0, F1), o + c) + 0.5);
    if (i < 0.0 || i > n - 1.0) continue;
    float ph = TAU * pnMadfrac(i, PN_PHI - 1.0);
    float ct = m - 2.0 * i / n;
    float st = sqrt(max(0.0, 1.0 - ct * ct));
    vec3 q = vec3(cos(ph) * st, sin(ph) * st, ct);
    vec3 dq = q - p;
    float d2 = dot(dq, dq);
    if (d2 < dBest) { dBest = d2; jBest = i; qBest = q; }
  }
  return jBest;
}

// Keystroke impact point on the visible hemisphere.
vec3 pnImpact(float s) {
  float a = fract(s * 5.17 + 0.31) * TAU;
  float b = fract(s * 11.39 + 0.77);
  float rho = 0.35 + 0.6 * b;
  return vec3(cos(a) * rho, sin(a) * rho, sqrt(max(1.0 - rho * rho, 0.0)));
}
float pnFade(float age) { return 1.0 - smoothstep(0.75, 1.1, age); }

// Radial burst of the dot field in view direction n: a front races out from each impact, throws
// the dots outward and lets them spring back with a damped wobble.
float pnBurst(vec3 n) {
  float d = 0.0;
  for (int k = 0; k < 4; k++) {
    float S = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    if (S <= 0.0) continue;
    float age = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    float seed = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
    float g = acos(clamp(dot(n, pnImpact(seed)), -1.0, 1.0));
    float x = 0.08 + age * 2.4 - g;
    float xp = max(x, 0.0);
    float push = smoothstep(-0.3, 0.0, x) * exp(-xp * 2.6) * cos(xp * 7.0);
    d += push * S * pnFade(age) / (0.8 + age);
  }
  return d;
}

// Shared dot colour: cyan/blue on one side, magenta/pink with a warm red edge on the other.
vec3 pnColor(vec3 nv, float hj, bool light) {
  float side = clamp(nv.x * 1.25 + (hj - 0.5) * 0.5, -1.0, 1.0);
  vec3 cold = mix(vec3(0.15, 0.45, 1.0), vec3(0.1, 0.85, 1.0), smoothstep(0.0, 1.0, nv.y * 0.5 + 0.5 - side * 0.3));
  vec3 warm = mix(vec3(0.95, 0.22, 0.85), vec3(1.0, 0.25, 0.45), smoothstep(0.2, 1.0, side));
  warm = mix(warm, vec3(1.0, 0.3, 0.24), smoothstep(0.75, 1.0, side) * 0.6);
  vec3 c = mix(cold, warm, smoothstep(-0.35, 0.35, side));
  if (light) c = c * vec3(0.62, 0.58, 0.82);
  return c;
}

// One hemisphere (sgn = +1 front, -1 back) of a dot shell. Returns colour (premultiplied) + alpha.
vec4 pnShell(vec2 P, float R, float N, mat3 M, float sgn, float amp, float dotR, float pxW, float sid, bool light, float yMask) {
  vec2 Q = P / R;
  if (dot(Q, Q) > 2.4) return vec4(0.0);
  float d0 = uImpulse * 0.07;
  vec3 n = vec3(0.0, 0.0, 1.0);
  for (int it = 0; it < 2; it++) {
    vec2 q2 = Q / (1.0 + d0);
    float l2 = dot(q2, q2);
    if (l2 > 0.9999) { q2 *= 0.99995 * inversesqrt(l2); l2 = 0.9999; }
    n = vec3(q2, sgn * sqrt(1.0 - l2));
    d0 = amp * pnBurst(n) + uImpulse * 0.07;
  }
  vec3 ql;
  float j = pnNearest(M * n, N, ql);
  vec3 nq = ql * M;
  if (nq.z * sgn < -0.02) return vec4(0.0);
  float hj = fract(sin(j * 12.9898 + sid * 78.233) * 43758.5453);
  float dq = amp * pnBurst(nq) * (0.85 + 0.3 * hj) + uImpulse * 0.07;
  vec2 sp = R * (1.0 + dq) * nq.xy;
  float dd = length(P - sp);
  float hot = clamp(dq * 3.0, 0.0, 1.0);
  float rad = dotR * (sgn > 0.0 ? 1.0 : 0.62) * (1.0 + hot * 0.6);
  float cov = 1.0 - smoothstep(rad - pxW * 0.7, rad + pxW * 0.7, dd);
  cov *= min(1.0, rad / pxW);
  float glow = exp(-dd * dd / (rad * rad * 9.0)) * 0.22;
  // Flowing ribbons of lit dots across the shell, plus a slow twinkle.
  float f = fbm2(ql * 2.1 + vec3(sid * 3.7, uTime * 0.07, -uTime * 0.05));
  float ridge = 1.0 - abs(2.0 * f - 1.0);
  float lit = 0.16 + 0.84 * smoothstep(0.55, 0.92, ridge);
  lit *= 0.75 + 0.25 * sin(uTime * 2.3 + hj * TAU);
  // Forging: bands of dots pulse.
  float band = 0.5 + 0.5 * sin(nq.y * 9.0 - uTime * 5.0 + sid);
  lit *= 1.0 + uPulse * 1.4 * pow(band, 4.0);
  lit *= sgn > 0.0 ? 1.0 : 0.42;
  lit *= 1.0 + hot * 1.8;
  vec3 c = pnColor(nq, hj, light);
  c = mix(c, vec3(1.0, 0.85, 0.95), hot * 0.35);
  float a = (cov + (light ? glow * 0.3 : glow)) * lit * yMask;
  return vec4(c * a, a);
}

// A dotted ribbon wrapping the sphere on a tilted shell of radius Rr. Returns colour + alpha.
vec4 pnRibbon(vec2 P, float Rr, mat3 M, float sgn, float flow, float nU, float seed, vec3 rc, float pxW, bool light, float yMask) {
  float l2 = dot(P, P) / (Rr * Rr);
  if (l2 >= 1.0) return vec4(0.0);
  vec3 p = vec3(P / Rr, sgn * sqrt(1.0 - l2));
  vec3 lp = M * p;
  float az = atan(lp.z, lp.x);
  float uu = az / TAU * nU - flow;
  float jI = floor(uu + 0.5);
  float azJ = (jI + flow) / nU * TAU;
  float cl = 0.24 * sin(2.0 * azJ + seed) + 0.1 * sin(3.0 * azJ - uTime * 0.4 + seed * 2.0);
  float w = 0.11 + 0.05 * sin(azJ * 3.0 + uTime * 0.3 + seed);
  float lat = asin(clamp(lp.y, -1.0, 1.0));
  float v = (lat - cl) / w * 3.0;
  float kI = clamp(floor(v + 0.5), -3.0, 3.0);
  float latK = cl + kI * w / 3.0;
  vec3 dl = vec3(cos(latK) * cos(azJ), sin(latK), cos(latK) * sin(azJ));
  vec3 dv = dl * M;
  if (dv.z * sgn < -0.02) return vec4(0.0);
  vec2 sp = Rr * (1.0 + uImpulse * 0.05) * dv.xy;
  float dd = length(P - sp);
  float rad = (sgn > 0.0 ? 0.0115 : 0.0075) * (1.0 - abs(kI) * 0.09);
  float cov = 1.0 - smoothstep(rad - pxW * 0.7, rad + pxW * 0.7, dd);
  cov *= min(1.0, rad / pxW);
  float glow = exp(-dd * dd / (rad * rad * 9.0)) * 0.2;
  float head = pow(0.5 + 0.5 * sin(azJ - flow * 0.35 + seed), 2.0);
  float lit = (0.25 + 0.75 * head) * (1.0 - abs(kI) * 0.1) * (sgn > 0.0 ? 1.0 : 0.38);
  lit *= 1.0 + uPulse * 0.6;
  vec3 c = light ? rc * vec3(0.62, 0.58, 0.82) : rc;
  float a = (cov + (light ? glow * 0.3 : glow)) * lit * yMask;
  return vec4(c * a, a);
}

void pnAdd(inout vec3 col, inout float alpha, vec4 s, bool light) {
  if (light) { col = s.rgb + col * (1.0 - s.a); alpha = s.a + alpha * (1.0 - s.a); }
  else { col += s.rgb; alpha += s.a; }
}

vec4 core(vec2 uv) {
  vec2 P = uv / uRadius;
  float rP = length(P);
  float pxW = uPx / uRadius;
  bool light = uLight > 0.5;
  float e = uEnergy;
  vec3 col = vec3(0.0);
  float alpha = 0.0;

  // Nebula haze behind the dots.
  float hz = exp(-rP * rP * 1.6) * 0.22 + exp(-pow(max(rP - 0.92, 0.0) * 6.0, 2.0)) * smoothstep(0.5, 1.0, rP) * 0.1;
  vec3 hzc = mix(vec3(0.15, 0.3, 1.0), vec3(0.85, 0.2, 0.75), smoothstep(-0.8, 0.8, P.x));
  float hza = hz * (light ? 0.25 : 1.0) * (1.0 + uPulse * 0.5 + e * 0.4);
  pnAdd(col, alpha, vec4(hzc * hza * (light ? 0.7 : 0.6), hza * 0.6), light);

  vec4 yf = yFlat(P, 0.9, pxW);
  float yHalo = yFlatGlow(P, 0.9, 0.05);
  float yMask = 1.0 - smoothstep(0.25, 0.75, yHalo);

  mat3 M0 = rotY(uSwirl * 0.55) * rotX(0.5);
  mat3 M1 = rotY(-uSwirl * 0.8) * rotZ(0.9) * rotX(-0.3);
  mat3 M2 = rotY(uSwirl * 1.1 + 1.0) * rotX(1.2);
  mat3 RA = rotX(-0.35) * rotZ(0.32);
  mat3 RB = rotX(0.5) * rotZ(-0.55);
  float flowA = uSwirl * 9.0;
  float flowB = -uSwirl * 7.0 + 40.0;
  vec3 cA = vec3(0.2, 0.75, 1.0);
  vec3 cB = vec3(1.0, 0.3, 0.7);
  float pxD = pxW;

  // Back to front.
  pnAdd(col, alpha, pnRibbon(P, 1.12, RA, -1.0, flowA, 260.0, 0.0, cA, pxD, light, 1.0), light);
  pnAdd(col, alpha, pnRibbon(P, 1.04, RB, -1.0, flowB, 240.0, 2.0, cB, pxD, light, 1.0), light);
  pnAdd(col, alpha, pnShell(P, 1.0, 3200.0, M0, -1.0, 0.42, 0.0105, pxD, 0.0, light, 1.0), light);
  pnAdd(col, alpha, pnShell(P, 0.8, 2000.0, M1, -1.0, 0.32, 0.0095, pxD, 1.0, light, 1.0), light);
  pnAdd(col, alpha, pnShell(P, 0.6, 1100.0, M2, -1.0, 0.24, 0.009, pxD, 2.0, light, 1.0), light);

  // The Y with a halo.
  vec3 ybase = yf.rgb;
  float yg = yHalo * (1.0 - yf.a);
  vec3 yGlowC = mix(vec3(0.35, 0.6, 1.0), vec3(0.9, 0.35, 1.0), smoothstep(-0.4, 0.4, P.x));
  pnAdd(col, alpha, vec4(yGlowC * yg * (light ? 0.25 : 0.55), yg * (light ? 0.2 : 0.45)) * (1.0 + uPulse * 0.4 + uKick * 0.5), light);
  vec3 yc = light ? yf.rgb * 0.92 : yf.rgb * (1.1 + uPulse * 0.35 + uKick * 0.3);
  col = mix(col, yc * yf.a, yf.a);
  alpha = mix(alpha, 1.0, yf.a);

  pnAdd(col, alpha, pnShell(P, 0.6, 1100.0, M2, 1.0, 0.24, 0.009, pxD, 2.0, light, yMask), light);
  pnAdd(col, alpha, pnShell(P, 0.8, 2000.0, M1, 1.0, 0.32, 0.0095, pxD, 1.0, light, yMask), light);
  pnAdd(col, alpha, pnShell(P, 1.0, 3200.0, M0, 1.0, 0.42, 0.0105, pxD, 0.0, light, yMask), light);
  pnAdd(col, alpha, pnRibbon(P, 1.04, RB, 1.0, flowB, 240.0, 2.0, cB, pxD, light, mix(1.0, yMask, 0.7)), light);
  pnAdd(col, alpha, pnRibbon(P, 1.12, RA, 1.0, flowA, 260.0, 0.0, cA, pxD, light, mix(1.0, yMask, 0.7)), light);

  // Fade everything well before the canvas edge.
  float edge = 1.0 - smoothstep(1.45, 1.72, rP);
  alpha = clamp(alpha, 0.0, 1.0) * edge;
  col = tonemap(col) * edge;
  float dith = (hash2(gl_FragCoord.xy) - 0.5) / 255.0;
  col = clamp(col + dith * alpha, 0.0, 1.0);
  return vec4(min(col, vec3(alpha)), alpha);
}
