import type { CoreConcept } from "../types";

/**
 * Aurora Shell — a dark glass sphere with a crisp neon rim. Inside, twisting silk ribbons live on
 * nested shells (evaluated analytically at the refracted ray's front and back hits): two-tone faces,
 * fine threads, edge-on sheen and a soft halo. The 3D Y floats inside and reflects the silk.
 * Keystrokes flare the rim at the impact angle, throw a corona outward and sweep a hue wave
 * through the ribbons.
 */
export const aurora: CoreConcept = {
  id: "aurora",
  name: "Aurora Shell",
  kind: "3D",
  tagline: "Silk light inside a neon rim",
  description: "Work in progress.",
  typing: "Work in progress.",
  extent: 1.75,
  frag: /* glsl */ `
// Impact angle of a keystroke on the rim.
float auAngle(float s) { return fract(s * 7.77 + 0.21) * TAU - PI; }
float auFade(float age) { return 1.0 - smoothstep(0.8, 1.12, age); }
float auWrap(float a) { return a - TAU * floor((a + PI) / TAU); }
// Mirror a palette coordinate back into -1..1 (a triangle wave), for hue shifts.
float auMirror(float h) { return 1.0 - abs(mod(h + 1.0, 4.0) - 2.0); }

// Hue-wave weight at a 3D point: fronts racing from each rim impact.
float auHueWave(vec3 p) {
  float w = 0.0;
  for (int k = 0; k < 4; k++) {
    float S = k == 0 ? uWaveS.x : k == 1 ? uWaveS.y : k == 2 ? uWaveS.z : uWaveS.w;
    if (S <= 0.0) continue;
    float age = k == 0 ? uWaveAge.x : k == 1 ? uWaveAge.y : k == 2 ? uWaveAge.z : uWaveAge.w;
    float seed = k == 0 ? uWaveSeed.x : k == 1 ? uWaveSeed.y : k == 2 ? uWaveSeed.z : uWaveSeed.w;
    float a = auAngle(seed);
    vec3 c = vec3(cos(a), sin(a), 0.0);
    float d = length(p - c);
    float f = age * 2.0;
    w += S * auFade(age) * exp(-pow((d - f) / 0.2, 2.0)) * 1.4;
  }
  return w;
}

// Silk ribbon on a sphere shell at point p (view space). M = ribbon frame (ribbon circles its y axis).
// cA / cB = palette coordinates of the two faces. Returns emission (rgb) and density (a).
vec4 auRibbon(vec3 p, mat3 M, float seed, float flow, float w0, float hA, float hB, float pxW, float hueW) {
  vec3 lp = M * p;
  float rr = max(length(lp), 1e-4);
  vec3 ln = lp / rr;
  float az = atan(ln.z, ln.x);
  float lat = asin(clamp(ln.y, -1.0, 1.0));
  float rip = 0.035 * uEnergy + 0.045 * min(abs(uImpulse), 1.0);
  float cl = 0.3 * sin(2.0 * az + seed + flow * 0.7) + 0.12 * sin(3.0 * az - flow * 1.3 + seed * 1.7)
           + rip * sin(az * 7.0 - flow * 5.0 + seed);
  float tw = az + seed * 2.0 + flow * 0.9;
  float ct = cos(tw);
  float w = w0 * (0.6 + 0.4 * sin(az * 2.0 + seed * 3.0 + flow * 0.5));
  float hw = w * abs(ct) + 0.006;
  float dl = abs(lat - cl) * rr;
  float hwl = hw * rr;
  float aa = pxW * 1.3;
  float inside = 1.0 - smoothstep(hwl - aa, hwl + aa, dl);
  float v = clamp(dl / hwl, 0.0, 1.0);
  float sheen = pow(1.0 - abs(ct), 2.0);
  float along = 0.4 + 0.6 * pow(0.5 + 0.5 * sin(az + flow * 1.6 + seed), 2.0);
  // Fine threads across the width (faded out when they get finer than a few pixels).
  float spacing = 2.0 * hwl / 7.0;
  float thr = mix(1.0, 0.78 + 0.22 * cos(v * PI * 7.0), smoothstep(pxW * 2.5, pxW * 5.0, spacing));
  float edge = smoothstep(0.55, 1.0, v);
  float emis = along * (0.45 + 1.1 * sheen) * thr + edge * 0.45 * along;
  float face = smoothstep(-0.25, 0.25, ct);
  float h = mix(hB, hA, face) + sin(az * 2.0 + flow) * 0.15;
  h = auMirror(h + hueW * 1.3);
  vec3 c = palette(h);
  c = mix(c, vec3(1.0), sheen * 0.25 + edge * 0.15 + hueW * 0.25);
  float halo = exp(-max(dl - hwl, 0.0) / 0.055) * 0.16 * along;
  float boost = 1.0 + uPulse * 0.9 + hueW * 1.2;
  vec3 rgb = (c * emis * inside + palette(h) * halo) * boost;
  return vec4(rgb, (emis * inside + halo) * boost);
}

// Front/back hits of the ray o + d t with a sphere of radius r centred at the origin.
vec2 auShell(vec3 o, vec3 d, float r) {
  float b = dot(o, d);
  float c = dot(o, o) - r * r;
  float disc = b * b - c;
